using CondoManager.Domain;
namespace CondoManager.UnitTests;
public class MeetingDomainTests
{
 private static CondominiumMeeting Meeting()=>new(Guid.NewGuid(),Guid.NewGuid(),"Synthetic meeting",MeetingType.Ordinary,Guid.NewGuid());
 [Theory][InlineData(MeetingType.Ordinary)][InlineData(MeetingType.Extraordinary)] public void BothTypesStartDraft(MeetingType type){var m=new CondominiumMeeting(Guid.NewGuid(),Guid.NewGuid(),"Synthetic",type,Guid.NewGuid());Assert.Equal(MeetingStatus.Draft,m.Status);Assert.Equal(type,m.Type);}
 [Fact]public void ConvenedGeneralDataCannotChange(){var m=Meeting();m.Transition(MeetingStatus.Scheduled);m.Transition(MeetingStatus.Convened);Assert.Throws<InvalidOperationException>(()=>m.Configure("Changed",MeetingType.Ordinary,null,"Room",null,null));Assert.Throws<InvalidOperationException>(()=>m.Transition(MeetingStatus.Completed));}
 [Fact]public void ExplicitVersionIsRequired(){var m=Meeting();m.CheckVersion(1);m.Touch();Assert.Throws<InvalidOperationException>(()=>m.CheckVersion(1));}
 [Fact]public void SessionsDoNotAutomaticallyAdvance(){var s=new MeetingSession(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),MeetingCall.First,DateTimeOffset.UtcNow);s.Transition(SessionStatus.NotHeld);Assert.Equal(SessionStatus.NotHeld,s.Status);Assert.Throws<InvalidOperationException>(()=>s.Transition(SessionStatus.InProgress));}
 [Fact]public void ProxyRequiresDifferentPeopleAndManualVerification(){var person=Guid.NewGuid();Assert.Throws<ArgumentException>(()=>new MeetingProxy(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),person,person,DateTimeOffset.UtcNow,null,null));var p=new MeetingProxy(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),person,Guid.NewGuid(),DateTimeOffset.UtcNow,null,null);Assert.Throws<InvalidOperationException>(()=>p.Transition(ProxyStatus.Verified,person));p.Transition(ProxyStatus.Submitted,person);p.Transition(ProxyStatus.Verified,person);Assert.NotNull(p.VerifiedAt);p.Transition(ProxyStatus.Revoked,person);}
 [Fact]public void AttendanceCheckoutIsHistorical(){var a=new MeetingAttendance(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),AttendanceType.InPerson,null,null,DateTimeOffset.UtcNow,null);Assert.Throws<InvalidOperationException>(()=>a.Leave(a.CheckInAt.AddMinutes(-1)));a.Leave(DateTimeOffset.UtcNow);Assert.Throws<InvalidOperationException>(()=>a.Leave(DateTimeOffset.UtcNow));}
 [Fact]public void NoticeEventsMustNotImplyVerifiedDelivery(){var n=new MeetingNotice(Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),Guid.NewGuid(),"Synthetic","synthetic@test.invalid",NoticeChannel.Email);Assert.Throws<InvalidOperationException>(()=>n.Transition(NoticeStatus.Delivered,DateTimeOffset.UtcNow));n.Transition(NoticeStatus.Ready,DateTimeOffset.UtcNow);n.Transition(NoticeStatus.Sent,DateTimeOffset.UtcNow);n.Transition(NoticeStatus.Delivered,DateTimeOffset.UtcNow);Assert.NotNull(n.SentAt);}
 [Theory][InlineData("http://example.invalid")][InlineData("javascript:alert(1)")][InlineData("https://user:secret@example.invalid")]public void RemoteUrlMustBeSafeHttps(string url){var m=Meeting();Assert.Throws<ArgumentException>(()=>m.Configure("Synthetic",MeetingType.Ordinary,null,"Room",url,null));}
}
